<template>
  <div class="page">
    <div class="head"><div><div class="eyebrow">PENGATURAN · DOKUMEN</div><h3>Upload Slip Gaji</h3><p>Upload dan proses slip gaji berdasarkan NIP pegawai.</p></div><button class="btn btn-sm btn-outline-primary" @click="go('/pengaturan')"><i class="fas fa-arrow-left me-1"></i>Pengaturan</button></div>
    <div class="panel">
      <div class="slip-head"><div><h5><i class="fas fa-file-invoice-dollar me-2"></i>Upload Massal</h5><p>Nama file PDF wajib sama persis dengan NIP, contoh <strong>123456.pdf</strong>.</p></div><span class="count-badge">{{slipCount}} slip tersimpan</span></div>
      <div class="period-box"><div><label>Periode Slip Gaji</label><small>Pilih bulan slip yang akan diupload.</small></div><input v-model="periodeBulan" type="month" class="form-control form-control-sm period-input"></div>
      <div class="drop-zone" :class="{dragging}" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="onDrop" @click="fileInput?.click()"><i class="fas fa-cloud-arrow-up"></i><strong>Drag & Drop slip gaji di sini</strong><span>atau klik untuk memilih beberapa PDF</span></div>
      <input ref="fileInput" type="file" accept="application/pdf,.pdf" multiple hidden @change="onFiles">
      <div v-if="selectedFiles.length" class="selected-files"><div class="file-summary"><strong>{{selectedFiles.length}} file</strong><button class="btn btn-link btn-sm p-0 float-end" @click="clearFiles">Bersihkan</button></div><div v-for="file in selectedFiles" :key="file.name+'-'+file.size" class="file-row"><i class="fas fa-file-pdf text-danger"></i><span>{{file.name}}</span><small>{{sizeLabel(file.size)}}</small></div></div>
      <div class="actions"><button class="btn btn-primary btn-sm" :disabled="!selectedFiles.length||!periodeBulan||uploading" @click="previewSlips"><i class="fas fa-search me-1"></i>{{uploading?'Memvalidasi...':'Validasi Slip'}}</button><template v-if="previewRows.length"><select v-model="slipAction" class="form-select form-select-sm slip-action" :disabled="invalidCount>0||storing"><option value="simpan">Simpan saja</option><option value="email">Kirim email saja</option><option value="simpan_email">Simpan &amp; kirim email</option></select><button class="btn btn-success btn-sm" :disabled="invalidCount>0||storing" @click="storeSlips"><i class="fas fa-paper-plane me-1"></i>{{storing?'Memproses...':'Proses Slip'}}</button></template></div>
      <div v-if="previewRows.length" class="preview"><div class="preview-title"><div><h6>Preview Validasi</h6><small>Periode: {{periodeLabel(periodeBulan)}}</small></div><span>{{validCount}} valid · {{invalidCount}} bermasalah</span></div><div class="table-responsive"><table class="table table-sm table-bordered align-middle"><thead><tr><th>File</th><th>NIP</th><th>Pegawai</th><th>Status</th><th>Keterangan</th></tr></thead><tbody><tr v-for="item in previewRows" :key="item.filename"><td>{{item.filename}}</td><td>{{item.nip}}</td><td>{{item.pegawai?.nama||'-'}}</td><td><span class="status-pill" :class="item.valid?'valid':'invalid'">{{item.valid?(item.status==='replace'?'Ganti':'Valid'):(item.status||'Invalid')}}</span></td><td>{{item.message}}</td></tr></tbody></table></div></div>
    </div>
  </div>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import Swal from 'sweetalert2'
import api from '../../../services/api'
const router=useRouter();const go=(p)=>router.push(p);const loading=ref(false);const uploading=ref(false);const storing=ref(false);const dragging=ref(false);const fileInput=ref(null);const selectedFiles=ref([]);const previewRows=ref([]);const slipCount=ref(0);const periodeBulan=ref(`${new Date().getFullYear()}-${String(new Date().getMonth()+1).padStart(2,'0')}`);const slipAction=ref('simpan')
const validCount=computed(()=>previewRows.value.filter(x=>x.valid).length);const invalidCount=computed(()=>previewRows.value.filter(x=>!x.valid).length)
const load=async()=>{loading.value=true;try{const r=await api.get('/kehadiran/pengaturan');slipCount.value=Number(r.data?.data?.slip_gaji_count||0)}catch(e){await Swal.fire('Gagal',e.response?.data?.message||'Gagal memuat jumlah slip.','error')}finally{loading.value=false}}
const sizeLabel=(n)=>n<1024*1024?`${Math.round(n/1024)} KB`:`${(n/1024/1024).toFixed(2)} MB`;const periodeLabel=(v)=>{if(!v)return'-';const[a,b]=v.split('-');return new Intl.DateTimeFormat('id-ID',{month:'long',year:'numeric'}).format(new Date(Number(a),Number(b)-1,1))}
const addFiles=(files)=>{const pdfs=files.filter(f=>f.type==='application/pdf'||f.name.toLowerCase().endsWith('.pdf'));selectedFiles.value=[...selectedFiles.value,...pdfs.filter(f=>!selectedFiles.value.some(x=>x.name===f.name&&x.size===f.size))];previewRows.value=[]};const onFiles=(e)=>addFiles([...e.target.files]);const onDrop=(e)=>{dragging.value=false;addFiles([...e.dataTransfer.files])};const clearFiles=()=>{selectedFiles.value=[];previewRows.value=[];if(fileInput.value)fileInput.value.value=''}
const previewSlips=async()=>{if(!periodeBulan.value||!selectedFiles.value.length)return;uploading.value=true;try{const fd=new FormData();fd.append('periode_bulan',periodeBulan.value);selectedFiles.value.forEach(f=>fd.append('slip_gaji[]',f));const r=await api.post('/kehadiran/pengaturan/slip-gaji/preview',fd);previewRows.value=r.data?.data?.rows||[];if(!previewRows.value.length)throw new Error('Tidak ada hasil validasi.')}catch(e){const errors=e.response?.data?.errors;const first=errors?Object.values(errors)[0]?.[0]:null;await Swal.fire('Gagal',first||e.response?.data?.message||e.message||'Gagal memvalidasi slip gaji.','error')}finally{uploading.value=false}}
const storeSlips=async()=>{if(invalidCount.value)return;storing.value=true;try{const fd=new FormData();fd.append('periode_bulan',periodeBulan.value);fd.append('aksi',slipAction.value);selectedFiles.value.forEach(f=>fd.append('slip_gaji[]',f));const r=await api.post('/kehadiran/pengaturan/slip-gaji/store',fd);await Swal.fire('Berhasil',r.data?.message||'Slip gaji berhasil diproses.','success');clearFiles();await load()}catch(e){const errors=e.response?.data?.errors;const first=errors?Object.values(errors)[0]?.[0]:null;await Swal.fire('Gagal',first||e.response?.data?.message||'Gagal memproses slip gaji.','error')}finally{storing.value=false}}
onMounted(load)
</script>
<style scoped>
.page{padding:14px;background:#f4f7fb;min-height:100vh}.head{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:14px}.eyebrow{font-size:10px;font-weight:900;letter-spacing:.13em;color:#2563eb}.head h3{margin:2px 0 0;font-weight:950}.head p{margin:2px 0 0;color:#64748b;font-size:12px}.panel{background:#fff;border:1px solid #e5e7eb;border-radius:15px;padding:14px;box-shadow:0 .25rem .8rem rgba(15,23,42,.05)}.slip-head{display:flex;justify-content:space-between;gap:12px;align-items:center}.slip-head h5{margin:0;font-weight:950}.slip-head p{font-size:12px;color:#64748b;margin:3px 0}.count-badge{background:#eef2ff;color:#3730a3;border-radius:999px;padding:6px 10px;font-size:11px;font-weight:800}.period-box{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:10px;border:1px solid #dbeafe;background:#eff6ff;border-radius:12px;margin-top:12px}.period-box label{display:block;font-size:11px;font-weight:800;color:#1e3a8a}.period-box small{color:#64748b}.period-input{max-width:220px}.drop-zone{margin-top:10px;border:2px dashed #94a3b8;border-radius:14px;min-height:145px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:5px;cursor:pointer;background:#f8fafc}.drop-zone.dragging{border-color:#2563eb;background:#eff6ff}.drop-zone i{font-size:31px;color:#2563eb}.drop-zone strong{font-size:14px}.drop-zone span{font-size:12px;color:#64748b}.selected-files{margin-top:10px;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden}.file-summary{padding:7px 10px;background:#f8fafc}.file-row{display:flex;align-items:center;gap:8px;padding:7px 10px;border-top:1px solid #eef2f7;font-size:12px}.file-row span{flex:1}.file-row small{color:#64748b}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.slip-action{width:190px;min-width:190px}.preview{margin-top:14px}.preview-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.preview-title h6{margin:0;font-weight:950}.preview-title small{color:#64748b}.table{font-size:12px}.table th{white-space:nowrap;background:#f8fafc}.status-pill{padding:3px 8px;border-radius:999px;font-size:11px;font-weight:800}.status-pill.valid{background:#dcfce7;color:#166534}.status-pill.invalid{background:#fee2e2;color:#991b1b}@media(max-width:768px){.head{align-items:flex-start}.slip-head,.period-box{flex-direction:column;align-items:flex-start}.period-input{max-width:none;width:100%}.slip-action{width:100%;min-width:0}}
</style>
